/* Read-only OOXML list reader. Never executes macros or formulas. */
window.readForbiddenWorkbook=async function(file){
 if(file.size>15_000_000)throw Error('금지어 파일은 15MB 이하만 지원합니다. TXT 목록을 사용해주세요.');
 const data=new Uint8Array(await file.arrayBuffer()),view=new DataView(data.buffer),decoder=new TextDecoder();
 let end=-1;for(let i=data.length-22;i>=Math.max(0,data.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break;}
 if(end<0)throw Error('암호가 없는 XLSM/XLSX 또는 TXT 파일을 사용해주세요.');
 let count=view.getUint16(end+10,true),offset=view.getUint32(end+16,true);if(count>2000)throw Error('파일이 너무 복잡합니다. 금지어만 TXT로 불러오세요.');
 const entries=new Map();for(let i=0;i<count;i++){if(offset+46>data.length||view.getUint32(offset,true)!==0x02014b50)throw Error('잘못된 Excel 압축 구조입니다.');const flags=view.getUint16(offset+8,true),method=view.getUint16(offset+10,true),size=view.getUint32(offset+20,true),raw=view.getUint32(offset+24,true),n=view.getUint16(offset+28,true),extra=view.getUint16(offset+30,true),comment=view.getUint16(offset+32,true),local=view.getUint32(offset+42,true);const name=decoder.decode(data.slice(offset+46,offset+46+n));entries.set(name,{flags,method,size,raw,local});offset+=46+n+extra+comment;}
 async function xml(name){const e=entries.get(name);if(!e)throw Error('필요한 Excel 시트 정보를 찾지 못했습니다.');if(e.flags&1||e.raw>10_000_000)throw Error('암호화되었거나 시트 크기가 너무 큽니다.');const p=e.local;if(p+30>data.length||view.getUint32(p,true)!==0x04034b50)throw Error('잘못된 파일 헤더입니다.');const at=p+30+view.getUint16(p+26,true)+view.getUint16(p+28,true);if(at+e.size>data.length)throw Error('파일이 손상되었습니다.');let bytes=data.slice(at,at+e.size);if(e.method===8){if(typeof DecompressionStream==='undefined')throw Error('XLSM 읽기는 최신 Chrome 또는 Edge를 사용해주세요.');const reader=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();let chunks=[],total=0;while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>10_000_000){await reader.cancel();throw Error('시트 압축 해제 크기가 너무 큽니다.');}chunks.push(value);}bytes=new Uint8Array(total);let i=0;for(const c of chunks){bytes.set(c,i);i+=c.length;}}else if(e.method!==0)throw Error('지원하지 않는 Excel 압축 형식입니다.');if(bytes.length!==e.raw)throw Error('파일 크기 검증에 실패했습니다.');const text=decoder.decode(bytes);if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('외부 XML 선언은 지원하지 않습니다.');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('Excel XML을 읽지 못했습니다.');return doc;}
 const workbook=await xml('xl/workbook.xml'),sheet=[...workbook.getElementsByTagName('sheet')].find(s=>s.getAttribute('name')==='금지어삭제');if(!sheet)throw Error('‘금지어삭제’ 시트가 없습니다. 목록만 TXT 또는 붙여넣기로 넣어주세요.');
 const relId=sheet.getAttribute('r:id'),rels=await xml('xl/_rels/workbook.xml.rels'),rel=[...rels.getElementsByTagName('Relationship')].find(r=>r.getAttribute('Id')===relId);if(!rel||rel.getAttribute('TargetMode')==='External')throw Error('외부 시트는 읽지 않습니다.');const target=rel.getAttribute('Target');const sheetPath=target.startsWith('/')?target.slice(1):'xl/'+target;if(sheetPath.includes('..'))throw Error('지원하지 않는 시트 경로입니다.');
 const strings=entries.has('xl/sharedStrings.xml')?[...(await xml('xl/sharedStrings.xml')).getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];
 const sheetDoc=await xml(sheetPath),terms=[];let header='';for(const c of sheetDoc.getElementsByTagName('c')){const coordinate=c.getAttribute('r');if(!/^B\d+$/.test(coordinate))continue;const row=Number(coordinate.slice(1));const type=c.getAttribute('t');let value=c.getElementsByTagName('v')[0]?.textContent||'';if(type==='s')value=strings[Number(value)]??'';else if(type==='inlineStr')value=[...c.getElementsByTagName('t')].map(t=>t.textContent).join('');if(row===5)header=value.trim();if(row>=6&&value.trim())terms.push(value.trim());}
 if(header!=='금지어')throw Error('B5의 금지어 제목을 확인하지 못했습니다. 목록만 직접 붙여넣어주세요.');if(!terms.length)throw Error('금지어 목록이 비어 있습니다.');return [...new Set(terms)];
};
